/// <summary>
/// The <c>AVAPriceIncreaseDetectPriceDiscGroupsService</c> class is the service class for <c>AVAPriceIncreaseDetectPriceDiscGroups</c>
/// </summary>
class AVAPriceIncreaseDetectPriceDiscGroupsService extends SysOperationServiceBase
{
    AVAPriceIncreaseDetectPriceDiscGroupsContract   dataContract;
    boolean                                         lJobMode;

    int                                             runtime;

}

Method.Source:
/// <summary>
///    AVA <c>runService</c> method.
/// </summary>
/// <param name="_dataContract">
///    <c>AVAPriceIncreaseContract</c> as type
/// </param>
void runService(AVAPriceIncreaseDetectPriceDiscGroupsContract _dataContract)
{
    timeofDay                       time;
    AVAPriceIncreaseSet             locAVAPriceIncreaseSet;
    AVAPriceIncreaseTable           locTableBuffer;
    AVAPriceIncreasePriceDiscGroup  locAVAPriceIncreasePriceDiscGroup;

    #OCCRetryCount


    dataContract            = _dataContract;

    locAVAPriceIncreaseSet  = dataContract.parmAVAPriceIncreaseSet();

    time        = DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone());
    lJobMode    = false;

    if(this.isExecutingInBatch())
    {
        lJobMode    = true;
    }
    dataContract.parmlJobMode(lJobMode);

    try
    {
        if(!dataContract.parmAVAPriceIncreaseSet())
        {
            throw error("@SYS27759");
        }

        locTableBuffer  = AVAPriceIncreaseTable::find(locAVAPriceIncreaseSet);

        ttsbegin;
        if(locTableBuffer.RecId != 0)
        {
            if(locAVAPriceIncreasePriceDiscGroup.addFromAVAPriceIncreaseTable(locTableBuffer))
            {
                locAVAPriceIncreasePriceDiscGroup.countPriceGroupMembersFromAVAPriceIncreaseTable(locTableBuffer);
            }
        }
        ttscommit;

        runtime = DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()) - time;

        info(strfmt("@NDX:NXAOperationFinishedP1Min", runtime / 60));
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}
